 const auto &o=s.object(source);const auto paint=o.painted;const auto binding=o.material_bindings;auto mesh=o.deformation?o.deformation->preview(o.painted->mesh()):o.painted->mesh();const auto destination=target(s,mesh,legacy);s.select(destination);const auto before=s.encode();const auto native=s.snapshot();require(bake_object(s,source,settings()).projected>500,"Actual canonical SOURCE Bake projects through native target adapter");require(s.object(source).painted==paint&&s.object(source).material_bindings==binding,"Canonical source owners remain exact through Bake");
 double maximum=0,color_error=0,negative_omit=0,negative_swap=0,negative_domain=0;size_t interior=0;const auto material=live?detail::EmissionExportAccess::other_channels(*s.object(source).painted,s.object(source).material,{}):s.object(source).painted->preview(s.object(source).material);double emission_error=0,emission_peak=0;const auto &low=s.active().painted->mesh();for(size_t y=0;y<64;++y)for(size_t x=0;x<64;++x){const std::array<double,2> q{(x+.5)/64.,(y+.5)/64.};for(size_t tri=0;tri<2;++tri){auto a=low.uv[low.indices[tri*3]],b=low.uv[low.indices[tri*3+1]],c=low.uv[low.indices[tri*3+2]];const double den=(b[1]-c[1])*(a[0]-c[0])+(c[0]-b[0])*(a[1]-c[1]);require(std::isfinite(den)&&std::abs(den)>1e-20,"Finite canonical target UV determinant");const double u=((b[1]-c[1])*(q[0]-c[0])+(c[0]-b[0])*(q[1]-c[1]))/den,v=((c[1]-a[1])*(q[0]-c[0])+(a[0]-c[0])*(q[1]-c[1]))/den;require(std::isfinite(u)&&std::isfinite(v),"Finite independent canonical barycentrics");if(std::min({u,v,1-u-v})<.08)continue;const std::array<float,3> bary{float(u),float(v),float(1-u-v)};for(size_t role=0;role<2;++role){const auto wanted=decode(s.object(source),tri,bary,role),actual=direction(s.active(),tri,bary,role);finite_sample(actual);for(size_t axis=0;axis<3;++axis){maximum=std::max(maximum,std::abs(wanted[axis]-actual[axis]));negative_omit=std::max(negative_omit,std::abs(wanted[axis]-decode(s.object(source),tri,bary,role,false,true)[axis]));negative_swap=std::max(negative_swap,std::abs(wanted[axis]-decode(s.object(source),tri,bary,1-role)[axis]));negative_domain=std::max(negative_domain,std::abs(wanted[axis]-decode(s.object(source),tri,bary,role,true)[axis]));}}const auto wanted=sample(material->color,q,true),actual=sample(s.active().painted->baked()->maps.color,q,true);finite_sample(wanted);finite_sample(actual);for(size_t axis=0;axis<3;++axis)color_error=std::max(color_error,std::abs(wanted[axis]-actual[axis]));if(live){const auto wanted_emission=physical(*s.object(source).painted,q);const auto &baked=*s.active().painted->baked();require(bool(baked.emission_field),"Actual repeated Bake retains independent FLOAT emission field");const auto value=baked.emission_field->sample(float(q[0]),float(q[1])).resolve({},1);finite_sample({value[0],value[1],value[2]});for(size_t axis=0;axis<3;++axis){emission_error=std::max(emission_error,std::abs(wanted_emission[axis]-value[axis]));emission_peak=std::max(emission_peak,wanted_emission[axis]);}}++interior;break;}}
 require(interior>300&&maximum<.035&&negative_omit>.05,"Actual second-Bake interior normals match independent renderer oracle and reject omission beyond unchanged .035 bound");if(!clear)require(negative_swap>.05&&(!reuv||negative_domain>.05),"Same actual second-Bake interiors distinguish both field roles and original normal UV");require(color_error<.025,"Current material UV/color/paint remain separate from original field sampling");if(live)require(emission_peak>1&&emission_error<2e-4,"Independent sparse-layer FLOAT radiance survives posed canonical-source repeated Bake without RGB8 clipping");
