int main(int argc,char **argv) try {
 if(argc==3&&std::string_view(argv[1])=="--sources"){
   auto scene=Scene::load(argv[2]);
   scene.erase(scene.active().id);
   std::cout<<scene.encode().dump()<<'\n';
   return 0;
 }
 if(argc!=2)return 2;
 const std::filesystem::path out=argv[1];
 std::filesystem::create_directories(out);
 for(bool clear:{false,true})canonical_source::affine_source(clear,out);
 for(bool legacy:{false,true})for(bool reuv:{false,true})for(bool keyed:{false,true})
   for(bool live:{false,true})for(bool clear:{false,true})
     canonical_source::exercise(legacy,reuv,keyed,live,clear,out);
 canonical_source::negatives(out);
 std::cout<<"PASS "<<canonical_source::checks<<" canonical source checks\n";
 return 0;
} catch(const std::exception &error) {
 std::cerr<<"FAIL "<<error.what()<<'\n';
 return 1;
}
